rule name: Phishing Email Detection
metadata:
  description: Detect phishing emails with embedded QR code
  author: [Your Name]
signature:
  let attachment = http.query within "*.pdf" of $file_hash;
  let qr_code = http.domain within attachment;
  let target_url = http.domain within qr_code;
  condition:
    target_url matches within "hxxps://corp-mfa-setup.com/enroll"

